CREATE TABLE sem.deployment_admission (
	release_id TEXT NOT NULL, 
	physical_id TEXT NOT NULL, 
	deployment_id TEXT NOT NULL, 
	kind TEXT NOT NULL, 
	content BYTEA NOT NULL, 
	content_digest TEXT NOT NULL, 
	CONSTRAINT pk_deployment_admission PRIMARY KEY (release_id, physical_id, deployment_id, kind)
);

CREATE TABLE sem.physical_contract (
	physical_id TEXT NOT NULL, 
	checks JSONB NOT NULL, 
	source_digest TEXT NOT NULL, 
	CONSTRAINT pk_physical_contract PRIMARY KEY (physical_id)
);

CREATE TABLE sem.release_finalization (
	release_id TEXT NOT NULL, 
	content_digest TEXT NOT NULL, 
	CONSTRAINT pk_release_finalization PRIMARY KEY (release_id)
);

ALTER TABLE sem.deployment_admission ADD CONSTRAINT fk_deployment_admission_release_id FOREIGN KEY(release_id) REFERENCES sem.release (release_id);

ALTER TABLE sem.release_finalization ADD CONSTRAINT fk_release_finalization_release_id FOREIGN KEY(release_id) REFERENCES sem.release (release_id);

CREATE OR REPLACE FUNCTION ops.execution_edge(lifecycle text,prior text,result text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $edge$
 SELECT EXISTS(SELECT FROM (VALUES
('analysis','candidate_open','candidate_closed'),
('analysis','captured_open','captured_closed'),
('evaluation_result','private','completed'),
('realization','writable','completed'),
('reference_grade_record','private','recorded'),
('reference_pass_record','private','recorded'),
('run','consolidating','cancelled_sealed'),
('run','consolidating','failed_sealed'),
('run','consolidating','finished'),
('run','created','cancelled_open'),
('run','created','consolidating'),
('run','created','failed_open'),
('run','created','running'),
('run','running','cancelled_open'),
('run','running','consolidating'),
('run','running','failed_open'),
('submission','held','accepted'),
('submission','held','refused'),
('submission','new','clean'),
('submission','new','context_refused'),
('submission','new','held'),
('task','awaiting_agent','cancelled'),
('task','awaiting_agent','running'),
('task','awaiting_agent_held','cancelled_held'),
('task','awaiting_agent_held','running_held'),
('task','pending','cancelled'),
('task','pending','running'),
('task','running','awaiting_agent'),
('task','running','cancelled'),
('task','running','done'),
('task','running','empty'),
('task','running','failed'),
('task','running','running'),
('task','running','running_held'),
('task','running_held','awaiting_agent_held'),
('task','running_held','cancelled_held'),
('task','running_held','done_held'),
('task','running_held','empty_held'),
('task','running_held','failed_held'),
('task','running_held','running_held')) allowed(lifecycle,prior,result) WHERE allowed.lifecycle=$1 AND allowed.prior=$2 AND allowed.result=$3)
$edge$;

CREATE OR REPLACE VIEW data.selected_fact AS SELECT f.realization_id, f.release_id, f.fact_id, f.subject_id, f.property_id, f.object_value_id, f.qualification_value_id 
FROM data.fact AS f JOIN data.selection AS s ON s.realization_id = f.realization_id AND s.release_id = f.release_id AND s.fact_id = f.fact_id;

GRANT CREATE ON SCHEMA sem TO corpus_sem_publisher;
ALTER TABLE sem.deployment_admission OWNER TO corpus_sem_publisher;
ALTER TABLE sem.physical_contract OWNER TO corpus_sem_publisher;
ALTER TABLE sem.release_finalization OWNER TO corpus_sem_publisher;
GRANT SELECT,INSERT,TRIGGER ON ALL TABLES IN SCHEMA sem TO corpus_sem_publisher WITH GRANT OPTION;
GRANT SELECT,TRIGGER ON ALL TABLES IN SCHEMA data TO corpus_sem_publisher WITH GRANT OPTION;
GRANT SELECT ON ALL TABLES IN SCHEMA ops TO corpus_sem_publisher WITH GRANT OPTION;
GRANT USAGE ON SCHEMA sem TO corpus_sem_publisher WITH GRANT OPTION;
DO $acl$ BEGIN EXECUTE format('REVOKE TEMP ON DATABASE %I FROM PUBLIC,corpus_sem_writer,corpus_sem_reader,corpus_sem_admitter,corpus_sem_evaluator',current_database()); EXECUTE format('GRANT TEMP ON DATABASE %I TO corpus_sem_publisher',current_database()); END $acl$;
GRANT USAGE ON SCHEMA sem,data,ops TO corpus_sem_admitter;
SET LOCAL ROLE corpus_sem_publisher;
DO $reference$ BEGIN IF to_regclass('pg_temp.semantic_physical_checks') IS NOT NULL THEN RAISE EXCEPTION 'preexisting physical contract workspace'; END IF; END $reference$;
